import gurobipy as gp
from gurobipy import GRB
products = []
benefit = {}
weight = {}
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        name = rec['values']['ProductName']
        products.append(name)
        try:
            benefit[name] = int(rec['values']['Value'])
        except Exception:
            raise ValueError(f'Missing or invalid Value for {name}')
        try:
            weight[name] = int(rec['values']['Weight'])
        except Exception:
            raise ValueError(f'Missing or invalid Weight for {name}')
    elif rec['source'] == 'capacity.csv':
        try:
            capacity = int(rec['values']['Capacity'])
        except Exception:
            raise ValueError('Missing or invalid Capacity in capacity.csv')
if len(products) == 0 or len(benefit) != len(products) or len(weight) != len(products):
    raise ValueError('Missing or incomplete product data')
if capacity is None:
    raise ValueError('Missing capacity data')
m = gp.Model('NY_Development')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((benefit[i] * x[i] for i in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[i] * x[i] for i in products)) <= capacity, name='total_capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')